import{_ as e,o as a,c as o,ag as s}from"./chunks/framework.DQQHyi2x.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),r={name:"guide/index.md"};function i(d,t,n,l,c,u){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Claude Deck is a self-hosted web application for visualizing and managing local AI coding agents. It started with <a href="https://docs.anthropic.com/en/docs/claude-code" target="_blank" rel="noreferrer">Claude Code</a> configuration and now includes stable Codex CLI support for tmux sessions, safe TOML settings, feature flags, diagnostics, MCP/plugin inventory, and redacted config exports.</p><h2 id="why-claude-deck" tabindex="-1">Why Claude Deck? <a class="header-anchor" href="#why-claude-deck" aria-label="Permalink to &quot;Why Claude Deck?&quot;">​</a></h2><p>Claude Code stores configuration across multiple JSON files and directories (<code>~/.claude.json</code>, <code>~/.claude/settings.json</code>, <code>.claude/settings.json</code>, <code>.mcp.json</code>, and more). Managing these files manually is tedious and error-prone. Claude Deck gives you a visual dashboard to:</p><ul><li><strong>See everything at a glance</strong> — dashboard with counts, session activity, and context window usage</li><li><strong>Edit configuration visually</strong> — no more hand-editing JSON files</li><li><strong>Manage MCP servers</strong> — add, test, and configure servers with OAuth support</li><li><strong>Track usage</strong> — monitor token costs, billing blocks, and daily/monthly trends</li><li><strong>Browse sessions</strong> — view conversation transcripts with tool use details</li><li><strong>Monitor live sessions</strong> — attach to running Claude Code and Codex terminals via Agent Bridge</li><li><strong>Switch providers intentionally</strong> — use shared surfaces for Claude Code and Codex CLI while unsupported provider-specific pages stay hidden or disabled</li><li><strong>Manage Codex safely</strong> — edit whitelisted TOML settings, inspect feature flags, and run CLI-backed inventory/mutation flows without exposing auth or prompt history</li></ul><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p>Claude Deck covers Claude Code configuration and the shared local-agent operations layer:</p><table tabindex="0"><thead><tr><th>Category</th><th>Features</th></tr></thead><tbody><tr><td><strong>Core Config</strong></td><td>Claude Code settings editor, Codex TOML settings editor, Codex feature flags, MCP servers, slash commands</td></tr><tr><td><strong>Extensions</strong></td><td>Plugins, hooks, permissions, agents, skills</td></tr><tr><td><strong>Monitoring</strong></td><td>Sessions, usage tracking, context window, Agent Bridge</td></tr><tr><td><strong>Customization</strong></td><td>Output styles, status line, memory</td></tr><tr><td><strong>Management</strong></td><td>Projects, plans, backup &amp; restore</td></tr></tbody></table><h2 id="provider-support" tabindex="-1">Provider Support <a class="header-anchor" href="#provider-support" aria-label="Permalink to &quot;Provider Support&quot;">​</a></h2><p>Claude Deck exposes provider capabilities and status through the Providers API. Claude Code remains the full-featured provider for usage, context, transcripts, plugins, hooks, agents, skills, memory, backup, and restore. Codex CLI support focuses on mixed tmux sessions, safe TOML configuration, feature flags, diagnostics, MCP/plugin inventory and safe CLI-backed mutations, and redacted export-only backups.</p><p>See <a href="/docs/guide/multi-provider-codex-v2.html">Multi-Provider and Codex CLI</a> for the supported, diagnostics-only, and unsupported Codex surfaces.</p><h2 id="tech-stack" tabindex="-1">Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th></tr></thead><tbody><tr><td>Backend</td><td>Python 3.11+ with FastAPI</td></tr><tr><td>Frontend</td><td>React 19 + TypeScript 6 + Vite 7</td></tr><tr><td>UI</td><td>shadcn/ui + Tailwind CSS</td></tr><tr><td>Charts</td><td>Recharts</td></tr><tr><td>Database</td><td>SQLite (async via SQLAlchemy + aiosqlite)</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/docs/guide/installation.html">Installation</a> — get Claude Deck running locally</li><li><a href="/docs/guide/quick-start.html">Quick Start</a> — explore the dashboard in 5 minutes</li><li><a href="/docs/guide/architecture.html">Architecture</a> — understand how the app is built</li></ul>',15)])])}const p=e(r,[["render",i]]);export{g as __pageData,p as default};
